import os
import json
from typing import Any, Dict, Optional

import requests


class TextContentSafety:
    """
    Applies category thresholds to decide whether to allow text using Azure AI Content Safety.
    Uses Azure AI Content Safety Analyze Text REST API.
    """

    def __init__(
        self,
        endpoint: Optional[str] = None,
        api_key: Optional[str] = None,
        thresholds: Optional[Dict[str, float]] = None,
        api_version: str = "2024-02-15-preview",
        session: Optional[requests.Session] = None,
    ):
        self.endpoint = (endpoint or os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT") or "").rstrip("/")
        self.api_key = api_key or os.getenv("AZURE_CONTENT_SAFETY_KEY") or ""
        self.api_version = api_version
        self.session = session or requests.Session()
        self.thresholds = thresholds or {
            "hate": 2.0,
            "self_harm": 2.0,
            "sexual": 2.0,
            "violence": 2.0,
        }

        if not self.endpoint:
            raise ValueError("Azure Content Safety endpoint is required (AZURE_CONTENT_SAFETY_ENDPOINT).")
        if not self.api_key:
            raise ValueError("Azure Content Safety API key is required (AZURE_CONTENT_SAFETY_KEY).")

    def analyze(self, text: str) -> Dict[str, Any]:
        url = f"{self.endpoint}/contentsafety/text:analyze?api-version={self.api_version}"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/json",
        }
        payload = {
            "text": text,
            "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
            "outputType": "FourSeverityLevels",
        }
        response = self.session.post(url, headers=headers, json=payload, timeout=30)
        response.raise_for_status()
        return response.json()

    @staticmethod
    def _normalize_category_name(name: str) -> str:
        name = name.strip().lower()
        mapping = {
            "hate": "hate",
            "selfharm": "self_harm",
            "self_harm": "self_harm",
            "sexual": "sexual",
            "violence": "violence",
        }
        return mapping.get(name.replace(" ", "").replace("-", "_"), name.replace(" ", "_"))

    def should_allow(self, text: str) -> Dict[str, Any]:
        result = self.analyze(text)

        blocked = False
        reasons = []
        category_severities: Dict[str, int] = {}

        analysis = result.get("categoriesAnalysis", []) or result.get("categories_analysis", [])
        for item in analysis:
            category = self._normalize_category_name(str(item.get("category", "")))
            severity = item.get("severity")
            if severity is None:
                continue
            try:
                severity_int = int(severity)
            except (TypeError, ValueError):
                continue

            category_severities[category] = severity_int
            threshold = self.thresholds.get(category)
            if threshold is not None and severity_int >= threshold:
                blocked = True
                reasons.append(
                    {
                        "category": category,
                        "severity": severity_int,
                        "threshold": threshold,
                    }
                )

        return {
            "allow": not blocked,
            "blocked": blocked,
            "reasons": reasons,
            "category_severities": category_severities,
            "raw": result,
        }


def decide_text_allowance(text: str, thresholds: Optional[Dict[str, float]] = None) -> Dict[str, Any]:
    """
    Convenience wrapper.
    """
    safety = TextContentSafety(thresholds=thresholds)
    return safety.should_allow(text)
